export async function detectGPUTier() {
  const gpu = (window as any).gpu || (navigator as any).gpu;
  if (!gpu) return 'TIER_0_CPU';

  const adapter = await gpu.requestAdapter({ powerPreference: 'high-performance' });
  if (!adapter) return 'TIER_1_WEBGL2';

  const info = adapter.info || (adapter.requestAdapterInfo ? await adapter.requestAdapterInfo() : null);
  const vendor = info?.vendor?.toLowerCase() || '';
  const architecture = info?.architecture?.toLowerCase() || '';

  // Tier 2: WebGPU Compute Shader (High-End GPU)
  if (architecture.includes('nvidia') || architecture.includes('apple') || vendor.includes('qualcomm')) {
    const device = await adapter.requestDevice();
    return { tier: 'TIER_2_WEBGPU', device, adapter };
  }

  // Tier 1: WebGL2 Fragment Shader (Mid-Range / Integrated)
  const canvas = document.createElement('canvas');
  const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
  if (gl) {
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    if (ext) {
      const renderer = gl.getParameter(ext.UNMASKED_RENDERER_WEBGL);
      return { tier: 'TIER_1_WEBGL2', renderer };
    }
  }

  return 'TIER_0_CPU';
}

export class MediaWorkspace {
  private worker: Worker;
  private offscreen: OffscreenCanvas;
  private stream: MediaStream | null = null;

  constructor(canvas: HTMLCanvasElement, width: number, height: number) {
    this.offscreen = canvas.transferControlToOffscreen();
    this.worker = new Worker(new URL('./render-worker.ts', import.meta.url), { type: 'module' });
    this.worker.postMessage({ canvas: this.offscreen, width, height }, [this.offscreen as any]);
  }

  public loadVideo(url: string) {
    this.worker.postMessage({ type: 'LOAD_MEDIA', url });
  }

  public destroy() {
    this.worker.postMessage({ type: 'CLEANUP' });
    this.worker.terminate();
    // Prevent the 'glitch' by forcing null state
    this.stream?.getTracks().forEach(t => t.stop());
    this.stream = null;
  }
}

