import { Lock, Unlock } from 'lucide-react';

export const ZenToggle = ({ isZen, onToggle }: { isZen: boolean; onToggle: () => void }) => (
  <button
    onClick={onToggle}
    className={
      'fixed top-4 right-4 z-50 p-2 rounded-full ' +
      'bg-black/5 dark:bg-white/10 backdrop-blur-md border border-white/10 ' +
      'text-white/50 hover:text-white transition-all duration-300'
    }
  >
    {isZen ? <Unlock size={16} /> : <Lock size={16} />}
  </button>
);

